def seed(vault):
    from .. import sealed
    from ..events import envelope
    events=vault.read().events
    own=COMPARTMENT['compartment']
    if not any(e.type==sealed.COMPARTMENT_CREATED and e.payload.get('compartment')==own for e in events):
        vault.append(envelope.new(sealed.COMPARTMENT_CREATED,vault.identity.id,payload=COMPARTMENT))
    existing={e.payload.get('demo_note_id') for e in events if e.type==sealed.NOTE_SEALED}
    existing_ciphertexts={e.payload.get('ciphertext') for e in events
                          if e.type==sealed.NOTE_SEALED and e.payload.get('compartment')==own}
    for payload in NOTES:
        if payload['demo_note_id'] not in existing and payload['ciphertext'] not in existing_ciphertexts:
            vault.append(envelope.new(sealed.NOTE_SEALED,vault.identity.id,payload=payload))
